      AutoCompactorPass(
        pass: pass,
        tokensBefore: tokensBefore,
        tokensAfter: tokensAfter,
        fallback: attempt.fallback,
        ok: true,
        summary: attempt.summary,
        hiddenRecords: attempt.hiddenRecords,
        summarizedMessages: attempt.summarizedMessages,
      ),
    );
