          done: true,
          success:
              !shouldCompact(tokensAfter, window, settings) &&
              !_overMessageCap(),
        );
      }
      hooks.onBothRolesFailed(attempt.error!);
      hooks.onPass(
        AutoCompactorPass(
          pass: pass,
          tokensBefore: tokensBefore,
          tokensAfter: tokensBefore,
          fallback: null,
          ok: false,
          error: attempt.error,
