    }

    // A no-op pass (the branch is already compacted at the leaf): stop
    // instead of spinning identical passes to maxPasses.
    if (attempt.noWork) {
      hooks.onPass(
        AutoCompactorPass(
          pass: pass,
          tokensBefore: tokensBefore,
          tokensAfter: tokensBefore,
          fallback: attempt.fallback,
