    // would fight the verdict just printed).
    _hubCompletePanels();
    _logDiagnostic(
      'over-window continuation exhausted sid=$_logSid '
      'passes=$passesRan tokens=$tokens '
      'window=$_effectiveContextWindow failure=$lastFailure',
