  /// The funnel's abort gate (issue #1085 round-1): an explicit user stop
  /// surfaces as [CancelledException] — no retry, no false "exhausted"
  /// verdict, no resumed task.
  void _throwIfUserAborted() {
    if (_runAbortRequested) {
