              attemptBudget,
            );
            attemptToken.cancel(timeout);
            compacting.ignore();
            throw timeout;
          },
        );
        if (record == null) {
          return (
            ok: true,
            error: null,
            noWork: true,
            summary: null,
            hiddenRecords: 0,
            summarizedMessages: 0,
