      content: rawContent is String
          ? rawContent
          : [
              for (final block in (rawContent as List?) ?? const [])
                ContentBlock.fromJson(block as Map<String, dynamic>),
            ],
      timestamp: DateTime.fromMillisecondsSinceEpoch(
        json['timestamp'] as int? ?? 0,
      ),
    );
  }
}

