    final resolver = config.modelRolesResolver;
    final role =
        resolver?.resolveRole(memoryModelRole) ??
        resolver?.resolveRole(smolModelRole);
    if (role != null) return role;
    return (model: _agent.state.model, stream: _streamFunction);
  }
}

